      {
        "name": "RestError Exception Handling",
        "passed": true,
        "reason": "Imports RestError from @azure/storage-blob. handleAzureError checks `error instanceof RestError` and inspects statusCode and code properties. Also handles generic Error separately."
      },
      {
        "name": "No Deprecated Packages",
        "passed": true,
        "reason": "No deprecated packages found. Only @azure/storage-blob and @azure/identity in dependencies. No azure-storage, azure-arm-*, ms-rest-azure, or @azure/ms-rest-* packages."
